// Ambil pesan dari request
const msg = $input.first().json.body.message || '';
const msgLow = msg.toLowerCase();

// Tentukan query Cypher berdasarkan topik pertanyaan
let cypher = '';

if (msgLow.includes('tracer') || msgLow.includes('waktu tunggu') || msgLow.includes('cepat kerja') || msgLow.includes('multinasional') || msgLow.includes('kesesuaian') || msgLow.includes('lulusan kerja') || msgLow.includes('alumni kerja') || msgLow.includes('karir') || msgLow.includes('pekerjaan') || msgLow.includes('alumni')) {
  const prodis = ['informatika', 'sistem informasi', 'arsitektur', 'teknik sipil', 'desain komunikasi visual', 'dkv', 'desain produk', 'akuntansi', 'manajemen', 'psikologi', 'ilmu komunikasi', 'komunikasi'];
  const matchedProdi = prodis.find(p => msgLow.includes(p));
  if (matchedProdi) {
    cypher = `
      MATCH (p:ProgramStudi)-[:HAS_TRACER_STUDY]->(ts:TracerStudy)
      WHERE toLower(p.name) CONTAINS '${matchedProdi}' OR toLower(p.code) CONTAINS '${matchedProdi}'
      OPTIONAL MATCH (p)-[:LEADS_TO_CAREER]->(car:CareerPath)
      RETURN p.name AS prodi, ts.tahun AS tahun, ts.jumlah_lulusan AS lulusan,
             ts.wt_kurang_6_bulan AS dapat_kerja_kurang_6_bln,
             ts.persen_wt_kurang_6_bulan AS persen_cepat_kerja,
             ts.persen_kesesuaian_selaras AS persen_kerja_sesuai_bidang,
             ts.lingkup_nasional AS kerja_skala_nasional,
             ts.lingkup_multinasional AS kerja_skala_multinasional,
             collect(DISTINCT car.name)[..6] AS prospek_karir
      ORDER BY ts.tahun DESC
    `;
  } else {
    cypher = `
      MATCH (p:ProgramStudi)-[:HAS_TRACER_STUDY]->(ts:TracerStudy {tahun: 2024})
      RETURN p.name AS prodi, ts.tahun AS tahun, ts.jumlah_lulusan AS total_lulusan,
             ts.wt_kurang_6_bulan AS dapat_kerja_kurang_6_bulan,
             ts.persen_wt_kurang_6_bulan AS persen_cepat_kerja,
             ts.persen_kesesuaian_selaras AS persen_sesuai_bidang,
             ts.lingkup_multinasional AS kerja_multinasional
      ORDER BY ts.persen_wt_kurang_6_bulan DESC
    `;
  }
} else if (msgLow.includes('biaya') || msgLow.includes('ukt') || msgLow.includes('spp') || msgLow.includes('bayar') || msgLow.includes('harga') || msgLow.includes('kuliah') || msgLow.includes('daftar')) {
  cypher = `
    MATCH (p:ProgramStudi)
    OPTIONAL MATCH (p)-[:HAS_TUITION_FEE]->(b:BiayaKuliah)
    RETURN p.name AS prodi, p.akreditasi AS akreditasi,
           b.spp AS spp, b.sks_kelas AS sks_kelas,
           b.sks_praktik AS sks_praktik, b.total_semester_1 AS total_semester_1
    ORDER BY p.name
  `;
} else if (msgLow.includes('beasiswa') || msgLow.includes('jaya 100') || msgLow.includes('gratis') || msgLow.includes('potongan') || msgLow.includes('diskon')) {
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:OFFERS_SCHOLARSHIP]->(bs:Beasiswa)
    RETURN bs.nama AS nama_beasiswa, bs.syarat AS syarat
    ORDER BY bs.nama
  `;
} else if (msgLow.includes('dosen') || msgLow.includes('pengajar') || msgLow.includes('professor') || msgLow.includes('prof') || msgLow.includes('dr.')) {
  cypher = `
    MATCH (l:Lecturer)-[:TEACHES_IN]->(p:ProgramStudi)
    WHERE toLower(p.name) CONTAINS toLower('${msg.replace(/'/g,'')}') OR
          toLower(p.code) CONTAINS toLower('${msg.replace(/'/g,'')}')
    RETURN l.name AS dosen, l.role AS jabatan, l.email AS email, p.name AS prodi
    LIMIT 15
  `;
} else if (msgLow.includes('peminatan') || msgLow.includes('konsentrasi') || msgLow.includes('spesialisasi')) {
  cypher = `
    MATCH (p:ProgramStudi)-[:HAS_SPECIALIZATION]->(sp:Peminatan)
    RETURN p.name AS prodi, collect(sp.name) AS peminatan, sp.waktu_pemilihan AS waktu_pemilihan
    ORDER BY p.name
  `;
} else if (msgLow.includes('syarat') || msgLow.includes('buta warna') || msgLow.includes('masuk') || msgLow.includes('ipa') || msgLow.includes('portofolio')) {
  cypher = `
    MATCH (p:ProgramStudi)-[:HAS_REQUIREMENT]->(sk:SyaratKhusus)
    RETURN p.name AS prodi, sk.syarat_khusus AS syarat_khusus, sk.latar_belakang AS latar_belakang
    ORDER BY p.name
  `;
} else if (msgLow.includes('mata kuliah') || msgLow.includes('kurikulum') || msgLow.includes('semester') || msgLow.includes('matkul') || msgLow.includes('mk')) {
  const semMatch = msgLow.match(/semester\s*(\d+)/);
  const semNum = semMatch ? semMatch[1] : null;
  if (semNum) {
    cypher = `
      MATCH (p:ProgramStudi)-[:OFFERS_COURSE]->(c:Course)
      WHERE c.semester = 'Semester ${semNum}'
      RETURN p.name AS prodi, c.name AS mata_kuliah, c.sks AS sks, c.semester AS semester
      ORDER BY p.name, c.name
      LIMIT 30
    `;
  } else {
    cypher = `
      MATCH (p:ProgramStudi)-[:OFFERS_COURSE]->(c:Course)
      WITH p, c ORDER BY c.semester, c.name
      RETURN p.name AS prodi, collect(DISTINCT c.semester + ': ' + c.name)[..15] AS sample_courses
      ORDER BY p.name
    `;
  }
} else if (msgLow.includes('faq') || msgLow.includes('ptn') || msgLow.includes('uang kembali') || msgLow.includes('pengembalian')) {
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:HAS_FAQ]->(f:FAQ)
    RETURN f.pertanyaan AS pertanyaan, f.jawaban AS jawaban
    LIMIT 10
  `;
} else if (msgLow.includes('fasilitas') || msgLow.includes('lab') || msgLow.includes('studio') || msgLow.includes('laboratorium')) {
  cypher = `
    MATCH (p:ProgramStudi)-[:HAS_FACILITY]->(f:Facility)
    RETURN p.name AS prodi, collect(f.name) AS fasilitas
    ORDER BY p.name
  `;
} else if (msgLow.includes('prodi') || msgLow.includes('program studi') || msgLow.includes('jurusan') || msgLow.includes('akreditasi')) {
  cypher = `
    MATCH (f:Faculty)-[:OFFERS_PROGRAM]->(p:ProgramStudi)
    RETURN f.name AS fakultas, p.name AS prodi, p.code AS kode,
           p.akreditasi AS akreditasi, p.degree AS gelar, p.duration AS durasi
    ORDER BY f.name, p.name
  `;
} else if (msgLow.includes('jalur') || msgLow.includes('rapor') || msgLow.includes('tes') || msgLow.includes('usm') || msgLow.includes('prestasi') || msgLow.includes('pendaftaran')) {
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:OFFERS_SCHOLARSHIP]->(bs:Beasiswa)
    WITH collect({nama: bs.nama, syarat: bs.syarat}) AS beasiswa
    MATCH (p:ProgramStudi)-[:HAS_REQUIREMENT]->(sk:SyaratKhusus)
    RETURN beasiswa,
           collect({prodi: p.name, syarat: sk.syarat_khusus}) AS syarat_prodi
  `;
} else {
  // Query umum - ambil overview
  cypher = `
    MATCH (u:University {code: 'UPJ'})
    OPTIONAL MATCH (u)-[:HAS_FACULTY]->(f:Faculty)-[:OFFERS_PROGRAM]->(p:ProgramStudi)
    OPTIONAL MATCH (u)-[:OFFERS_SCHOLARSHIP]->(bs:Beasiswa)
    OPTIONAL MATCH (u)-[:HAS_FAQ]->(faq:FAQ)
    RETURN u.name AS universitas, u.tagline AS tagline,
           collect(DISTINCT p.name + ' (' + p.akreditasi + ')') AS program_studi,
           collect(DISTINCT bs.nama)[..5] AS beasiswa,
           collect(DISTINCT faq.pertanyaan)[..3] AS faq_sample
    LIMIT 1
  `;
}

return [{
  json: {
    message: msg,
    cypher: cypher.trim()
  }
}];

// Ambil data dari Neo4j response
const neo4jResponse = $input.first().json;
const message = $('Build Cypher Query').first().json.message;

let contextText = '';

try {
  const results = neo4jResponse.results || [];
  if (results.length > 0 && results[0].data && results[0].data.length > 0) {
    const columns = results[0].columns || [];
    const rows = results[0].data.map(d => {
      const obj = {};
      columns.forEach((col, i) => { obj[col] = d.row[i]; });
      return obj;
    });
    contextText = JSON.stringify(rows, null, 2);
  } else {
    contextText = 'Tidak ada data spesifik ditemukan di Knowledge Graph.';
  }
} catch(e) {
  contextText = 'Error membaca data: ' + e.message;
}

const prompt = `Kamu adalah asisten informasi resmi Universitas Pembangunan Jaya (UPJ) yang membantu calon mahasiswa baru.

Data relevan dari Knowledge Graph UPJ:
${contextText}

Pertanyaan:
${message}

Instruksi:
- Jawab dengan ramah, informatif, dan terstruktur dalam Bahasa Indonesia
- Gunakan data di atas sebagai referensi utama
- Jika ada data biaya/beasiswa, tampilkan secara rapi dengan angka yang jelas
- Gunakan bullet point atau numbering untuk daftar
- Jika data tidak tersedia, sarankan menghubungi PMB UPJ di pmb.upj.ac.id
- Jangan sebut "Knowledge Graph" atau "Neo4j" kepada pengguna`;

return [{
  json: {
    message: message,
    context: contextText,
    prompt: prompt
  }
}];

